/// `Value = Str | Glob | Identifier | Number | MacroCall | SearchWord`
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Value {
    /// A `Str`.
    Str(Str),
    /// A `Glob`.
    Glob(Glob),
    /// A `Identifier`.
    Identifier(Identifier),
    /// A `Number`.
    Number(Number),
    /// A `MacroCall`.
    MacroCall(MacroCall),
    /// A `SearchWord`.
    SearchWord(SearchWord),
}

impl AstNode for Value {
    type Language = Lang;
    fn can_cast(kind: SyntaxKind) -> bool {
        Str::can_cast(kind)
            || Glob::can_cast(kind)
            || Identifier::can_cast(kind)
            || Number::can_cast(kind)
            || MacroCall::can_cast(kind)
            || SearchWord::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let node = match syntax.kind() {
            SyntaxKind::STR => Self::Str(Str { syntax }),
            SyntaxKind::GLOB => Self::Glob(Glob { syntax }),
            SyntaxKind::IDENTIFIER => Self::Identifier(Identifier { syntax }),
            SyntaxKind::NUMBER => Self::Number(Number { syntax }),
            SyntaxKind::MACRO_CALL => Self::MacroCall(MacroCall { syntax }),
            SyntaxKind::SEARCH_WORD => Self::SearchWord(SearchWord { syntax }),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::Str(it) => it.syntax(),
            Self::Glob(it) => it.syntax(),
            Self::Identifier(it) => it.syntax(),
            Self::Number(it) => it.syntax(),
            Self::MacroCall(it) => it.syntax(),
            Self::SearchWord(it) => it.syntax(),
        }
    }
}

impl From<Str> for Value {
    fn from(node: Str) -> Self {
        Self::Str(node)
    }
}

impl From<Glob> for Value {
    fn from(node: Glob) -> Self {
        Self::Glob(node)
    }
}

impl From<Identifier> for Value {
    fn from(node: Identifier) -> Self {
        Self::Identifier(node)
    }
}

impl From<Number> for Value {
    fn from(node: Number) -> Self {
        Self::Number(node)
    }
}

impl From<MacroCall> for Value {
    fn from(node: MacroCall) -> Self {
        Self::MacroCall(node)
    }
}

impl From<SearchWord> for Value {
    fn from(node: SearchWord) -> Self {
        Self::SearchWord(node)
    }
}

